package de.schaepi.puls180;
import android.content.*;import android.content.pm.PackageManager;import android.os.*;import android.bluetooth.*;import android.bluetooth.le.*;import java.util.*;
final class MainBluetoothReceiver{
private final Context context;private final Runnable changed;private final Handler handler=new Handler(Looper.getMainLooper());private BluetoothGatt gatt;private BluetoothLeScanner scanner;private boolean active,waiting;private int generation;private int readyAttempt=-1;
private static UUID uuid(String shortId){return UUID.fromString("0000"+shortId+"-0000-1000-8000-00805f9b34fb");}
MainBluetoothReceiver(Context c,Runnable r){context=c;changed=r;}
void start(){stop();if(!License.allowed(context))return;active=true;handler.postDelayed(this::waitForSignal,900);}
void stop(){active=false;handler.removeCallbacksAndMessages(null);closeAll();}
private boolean permissions(){return Build.VERSION.SDK_INT<31||context.checkSelfPermission("android.permission.BLUETOOTH_SCAN")==PackageManager.PERMISSION_GRANTED&&context.checkSelfPermission("android.permission.BLUETOOTH_CONNECT")==PackageManager.PERMISSION_GRANTED;}
private void closeGatt(){generation++;readyAttempt=-1;if(gatt!=null){try{gatt.disconnect();gatt.close();}catch(SecurityException ignored){}gatt=null;}}
private void stopWaiting(){if(scanner!=null&&waiting)try{scanner.stopScan(signal);}catch(SecurityException|IllegalStateException ignored){}waiting=false;scanner=null;}
private void closeAll(){stopWaiting();closeGatt();}
private void waitForSignal(){if(!active)return;if(!License.allowed(context)){stop();return;}SharedPreferences prefs=context.getSharedPreferences("bluetooth",0);if(!prefs.getBoolean("automatic",true)){closeAll();return;}String address=prefs.getString("device","");BluetoothManager manager=context.getSystemService(BluetoothManager.class);BluetoothAdapter adapter=manager==null?null:manager.getAdapter();if(!permissions()||adapter==null||!adapter.isEnabled()||!BluetoothAdapter.checkBluetoothAddress(address)||gatt!=null||waiting)return;try{scanner=adapter.getBluetoothLeScanner();if(scanner==null)return;ScanFilter filter=new ScanFilter.Builder().setDeviceAddress(address).build();ScanSettings settings=new ScanSettings.Builder().setScanMode(ScanSettings.SCAN_MODE_LOW_POWER).build();scanner.startScan(Collections.singletonList(filter),settings,signal);waiting=true;}catch(SecurityException|IllegalStateException e){waiting=false;scanner=null;handler.postDelayed(this::waitForSignal,30000);}}
private final ScanCallback signal=new ScanCallback(){@Override public void onScanResult(int type,ScanResult result){handler.post(()->{if(!active||!waiting||gatt!=null)return;BluetoothDevice device=result.getDevice();stopWaiting();connect(device);});}@Override public void onScanFailed(int error){handler.post(()->{waiting=false;scanner=null;if(active)handler.postDelayed(MainBluetoothReceiver.this::waitForSignal,30000);});}};
private void resumeWaiting(){if(active){handler.removeCallbacksAndMessages(null);handler.postDelayed(this::waitForSignal,1500);}}
private void connect(BluetoothDevice device){final int attempt=++generation;try{gatt=device.connectGatt(context,context instanceof MeasurementService,new BluetoothGattCallback(){
private boolean current(){return active&&attempt==generation;}
@Override public void onConnectionStateChange(BluetoothGatt g,int status,int state){handler.post(()->{if(!current())return;if(status!=BluetoothGatt.GATT_SUCCESS||state==BluetoothProfile.STATE_DISCONNECTED){closeGatt();resumeWaiting();return;}if(state==BluetoothProfile.STATE_CONNECTED){try{if(!g.discoverServices()){closeGatt();resumeWaiting();}}catch(SecurityException e){closeGatt();resumeWaiting();}}});}
@Override public void onServicesDiscovered(BluetoothGatt g,int status){handler.post(()->{if(!current())return;try{if(status!=BluetoothGatt.GATT_SUCCESS){closeGatt();resumeWaiting();return;}BluetoothGattService service=g.getService(uuid("1810"));BluetoothGattCharacteristic value=service==null?null:service.getCharacteristic(uuid("2a35"));BluetoothGattDescriptor config=value==null?null:value.getDescriptor(uuid("2902"));if(value==null||config==null||(value.getProperties()&BluetoothGattCharacteristic.PROPERTY_INDICATE)==0||!g.setCharacteristicNotification(value,true)){closeGatt();resumeWaiting();return;}if(Build.VERSION.SDK_INT>=33){if(g.writeDescriptor(config,BluetoothGattDescriptor.ENABLE_INDICATION_VALUE)!=BluetoothStatusCodes.SUCCESS){closeGatt();resumeWaiting();}}else{config.setValue(BluetoothGattDescriptor.ENABLE_INDICATION_VALUE);if(!g.writeDescriptor(config)){closeGatt();resumeWaiting();}}}catch(SecurityException e){closeGatt();resumeWaiting();}});}
@Override public void onDescriptorWrite(BluetoothGatt g,BluetoothGattDescriptor d,int status){handler.post(()->{if(!current())return;if(status!=BluetoothGatt.GATT_SUCCESS){closeGatt();resumeWaiting();return;}readyAttempt=attempt;try{BluetoothGattService svc=g.getService(uuid("1810"));BluetoothGattCharacteristic feat=svc==null?null:svc.getCharacteristic(uuid("2a49"));if(feat!=null)g.readCharacteristic(feat);}catch(SecurityException ignored){}handler.postDelayed(()->{if(current()&&!(context instanceof MeasurementService)){closeGatt();resumeWaiting();}},120000);});}
@Override public void onCharacteristicRead(BluetoothGatt g,BluetoothGattCharacteristic c,byte[] value,int status){if(!c.getUuid().equals(uuid("2a49"))||status!=BluetoothGatt.GATT_SUCCESS||value.length<2)return;boolean supported=(value[0]&4)!=0;handler.post(()->{if(!current())return;context.getSharedPreferences("bluetooth",0).edit().putBoolean("irregular:"+device.getAddress(),supported).apply();changed.run();});}
@Override public void onCharacteristicChanged(BluetoothGatt g,BluetoothGattCharacteristic c,byte[] value){if(!c.getUuid().equals(uuid("2a35")))return;byte[] packet=value.clone();handler.post(()->{if(!current())return;try(DirectStore store=new DirectStore(context)){boolean added=store.save(BleMeasurement.parse(packet),device.getAddress(),packet);if(added)changed.run();}catch(Exception e){android.widget.Toast.makeText(context,"Bluetooth-Messung konnte nicht gespeichert werden.",android.widget.Toast.LENGTH_LONG).show();}});}
},BluetoothDevice.TRANSPORT_LE);if(gatt==null)resumeWaiting();else handler.postDelayed(()->{if(active&&attempt==generation&&readyAttempt!=attempt&&!(context instanceof MeasurementService)){closeGatt();resumeWaiting();}},30000);}catch(SecurityException e){closeGatt();resumeWaiting();}}
}